void mainImage(out vec4 O, vec2 U)
{
        vec2 R = iResolution.xy,
             z = 1.5*(U+U - R) / R.y,
             c = vec2(.265,0),
             a;
        float s,i;
        for(;i++<60.;)// && dot(z,z)<4e5;)
        {
                //s += a.x+a.y;
                //s += exp(-abs(z.x*z.y));
                a = z;
                z = z*mat2(z.x,-z.y,z.yx);
                //z.x=-z.x;
                z+=c;
                if(dot(z,z)>4e5)break;
                //a = pow(abs(z-a), vec2(.25));
                //s += a.x+a.y;
                s += exp(-abs(z.x*z.y));
                //n++;
        }
        //if(n<1.)return;
        //s /= 8.;
        s /= 6.+sin(iTime*.3)*4.;// by diatribes   nice
        //s=n/60.;
        O = vec4(.5*(1.+sin(s)), 
                 sin(s),
                 .5*(1.-cos(s)),
                 1);
}
